import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  ArrowRight,
  ArrowUpRight,
  Dna,
  Droplet,
  Clock,
  Users,
  Award,
  Activity,
  Heart,
  Pill,
} from "lucide-react";

const HomePage = () => {
  const { t } = useTranslation();

  const services = [
    {
      icon: Dna,
      title: t("services.genetic.title"),
      desc: t("services.genetic.desc"),
      color: "#00E5A0",
    },
    {
      icon: Droplet,
      title: t("services.blood.title"),
      desc: t("services.blood.desc"),
      color: "#00E5A0",
    },
    {
      icon: Clock,
      title: t("services.bioage.title"),
      desc: t("services.bioage.desc"),
      color: "#00E5A0",
    },
    {
      icon: Users,
      title: t("services.dna.title"),
      desc: t("services.dna.desc"),
      color: "#00E5A0",
    },
    {
      icon: Pill,
      title: t("services.nutrition.title"),
      desc: t("services.nutrition.desc"),
      color: "#00E5A0",
    },
    {
      icon: Activity,
      title: t("services.hormones.title"),
      desc: t("services.hormones.desc"),
      color: "#00E5A0",
    },
  ];

  const stats = [
    { value: "98%", label: t("stats.accuracy") },
    { value: "50+", label: t("stats.analyses") },
    { value: "25+", label: t("stats.doctors") },
    { value: "10+", label: t("stats.sertificates") },
  ];

  return (
   
      <div className="min-h-screen" data-testid="home-page">
        {/* Hero Section */}
        <section
          className="relative min-h-screen flex items-center pt-20 overflow-hidden"
          style={{
            background: "linear-gradient(180deg, #F5F8FA 0%, #FFFFFF 100%)",
          }}
          data-testid="hero-section"
        >
          {/* Decorative Elements */}
          <div
            className="absolute top-32 right-20 w-96 h-96 rounded-full opacity-20"
            style={{
              background:
                "radial-gradient(circle, rgba(0,229,160,0.3) 0%, transparent 70%)",
            }}
          ></div>
          <div
            className="absolute bottom-20 left-10 w-64 h-64 rounded-full opacity-10"
            style={{
              background:
                "radial-gradient(circle, rgba(0,229,160,0.4) 0%, transparent 70%)",
            }}
          ></div>
          <div className="absolute top-1/2 right-1/4 w-px h-48 bg-gradient-to-b from-transparent via-[#00E5A0]/30 to-transparent"></div>

          {/* Decorative Arc */}
          <div className="absolute top-40 right-40 w-80 h-80 border-2 border-[#00E5A0]/10 rounded-full"></div>
          <div className="absolute top-48 right-48 w-64 h-64 border border-[#00E5A0]/20 rounded-full"></div>

          <div className="container relative z-10">
            <div className="grid lg:grid-cols-2 gap-12 items-center">
              {/* Left Content */}
              <div className="space-y-8">
                <div
                  className="inline-flex items-center gap-2 glass-card px-4 py-2"
                  data-testid="hero-tagline"
                >
                  <Activity className="w-4 h-4 text-[#00E5A0]" />
                  <span className="text-sm font-medium text-[#4A5A6E]">
                    {t("hero.tagline")}
                  </span>
                </div>

                <h1
                  className="text-5xl md:text-6xl lg:text-7xl font-bold leading-tight"
                  data-testid="hero-title"
                >
                  {t("hero.title")}{" "}
                  <span className="text-accent-gradient">
                    {t("hero.titleAccent")}
                  </span>
                  <br />
                  {t("hero.titleEnd")}
                </h1>

                <p
                  className="text-lg text-[#4A5A6E] max-w-lg leading-relaxed"
                  data-testid="hero-subtitle"
                >
                  {t("hero.subtitle")}
                </p>

                <div className="flex flex-wrap gap-4">
                  <Link
                    to="/services"
                    className="btn-primary flex items-center gap-2"
                    data-testid="hero-cta-primary"
                  >
                    {t("hero.cta")}
                    <ArrowRight className="w-5 h-5" />
                  </Link>
                  <Link
                    to="/appointment"
                    className="btn-secondary flex items-center gap-2"
                    data-testid="hero-cta-secondary"
                  >
                    {t("hero.ctaSecondary")}
                  </Link>
                </div>

                {/* Years Badge */}
                <div
                  className="glass-card inline-flex items-center gap-4 px-6 py-4"
                  data-testid="hero-years-badge"
                >
                  <div className="w-12 h-12 rounded-full bg-[#00E5A0]/10 flex items-center justify-center">
                    <Award className="w-6 h-6 text-[#00E5A0]" />
                  </div>
                  <div>
                    <p className="text-2xl font-bold text-[#1E2A3A]">
                      УНИКАЛЬНАЯ {t("hero.yearsLabel")}
                    </p>
                    <p className="text-sm text-[#4A5A6E]">
                      {t("hero.yearsText")}
                    </p>
                  </div>
                </div>
              </div>

              {/* Right Content - Image + Cards */}
              <div className="relative">
                {/* Main Image */}
                <div className="relative">
                  <div className="glass-card p-4 overflow-hidden">
                    <img
                      src="https://pravotorik.github.io/bio-code/img/home1.jpg"
                      alt="Doctor"
                      className="w-full h-[500px] object-cover rounded-2xl"
                      data-testid="hero-image"
                    />
                  </div>

                  {/* Floating Service Cards */}
                  <div
                    className="absolute -left-8 top-20 glass-card p-4 max-w-[200px] service-card"
                    data-testid="floating-card-1"
                  >
                    <div className="w-10 h-10 rounded-full bg-[#00E5A0]/10 flex items-center justify-center mb-3">
                      <Dna className="w-5 h-5 text-[#00E5A0]" />
                    </div>
                    <p className="text-sm font-semibold text-[#1E2A3A]">
                      {t("services.genetic.title")}
                    </p>
                  </div>

                  <div
                    className="absolute -right-4 bottom-32 glass-card p-4 max-w-[200px] service-card"
                    data-testid="floating-card-2"
                  >
                    <div className="w-10 h-10 rounded-full bg-[#00E5A0]/10 flex items-center justify-center mb-3">
                      <Droplet className="w-5 h-5 text-[#00E5A0]" />
                    </div>
                    <p className="text-sm font-semibold text-[#1E2A3A]">
                      {t("services.blood.title")}
                    </p>
                  </div>

                  {/* Stats Badge */}
                  <div
                    className="absolute -right-8 top-10 glass-card px-4 py-3 flex items-center gap-3"
                    data-testid="floating-stats"
                  >
                    <div className="text-center">
                      <p className="text-xl font-bold text-[#00E5A0]">10</p>
                      <p className="text-xs text-[#4A5A6E]">Сертификатов</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Stats Section */}
        <section className="py-20 section-alt" data-testid="stats-section">
          <div className="container">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
              {stats.map((stat, index) => (
                <div
                  key={index}
                  className="stat-card glass-card p-8 text-center"
                  data-testid={`stat-card-${index}`}
                >
                  <p className="text-4xl md:text-5xl font-bold text-[#00E5A0] mb-2">
                    {stat.value}
                  </p>
                  <p className="text-[#4A5A6E] font-medium">{stat.label}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* Services Section */}
        <section className="py-20 section-light" data-testid="services-section">
          <div className="container">
            <div className="text-center mb-16">
              <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-4">
                {t("about.tag")}
              </span>
              <h2 className="text-4xl md:text-5xl font-bold mb-4">
                {t("services.title")}
              </h2>
              <p className="text-lg text-[#4A5A6E] max-w-2xl mx-auto">
                {t("services.subtitle")}
              </p>
            </div>

            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
              {services.map((service, index) => {
                const Icon = service.icon;
                return (
                  <div
                    key={index}
                    className="service-card glass-card p-8 group cursor-pointer"
                    data-testid={`service-card-${index}`}
                  >
                    <div className="w-14 h-14 rounded-2xl bg-[#00E5A0]/10 flex items-center justify-center mb-6 group-hover:bg-[#00E5A0]/20 transition-colors duration-300">
                      <Icon className="w-7 h-7 text-[#00E5A0]" />
                    </div>
                    <h3 className="text-xl font-semibold text-[#1E2A3A] mb-3">
                      {service.title}
                    </h3>
                    <p className="text-[#4A5A6E] mb-4">{service.desc}</p>
                    <div className="flex items-center gap-2 text-[#00E5A0] font-medium group-hover:gap-3 transition-all duration-300">
                      <span>{t("about.learnMore")}</span>
                      <ArrowUpRight className="w-4 h-4" />
                    </div>
                  </div>
                );
              })}
            </div>

            <div className="text-center mt-12">
              <Link
                to="/services"
                className="btn-secondary inline-flex items-center gap-2"
                data-testid="view-all-services"
              >
                {t("services.viewAll")}
                <ArrowRight className="w-5 h-5" />
              </Link>
            </div>
          </div>
        </section>

        {/* About Section */}
        <section className="py-20 section-dark" data-testid="about-section">
          <div className="container">
            <div className="grid lg:grid-cols-2 gap-16 items-center">
              {/* Image */}
              <div className="relative">
                <div className="glass-card-dark p-4 overflow-hidden">
                  <img
                    src="https://pravotorik.github.io/bio-code/img/centre.jpg"
                    alt="Laboratory"
                    className="w-full h-[400px] object-cover rounded-2xl"
                    data-testid="about-image"
                  />
                </div>

                {/* Info Card */}
                <div
                  className="absolute -bottom-8 -right-8 glass-card p-6 max-w-[250px]"
                  data-testid="about-info-card"
                >
                  <div className="flex items-center gap-3 mb-3">
                    <div className="w-10 h-10 rounded-full bg-[#00E5A0] flex items-center justify-center">
                      <Heart className="w-5 h-5 text-[#0A1F44]" />
                    </div>
                    <span className="font-semibold text-[#1E2A3A]">
                      BIO-CODE
                    </span>
                  </div>
                  <p className="text-sm text-[#4A5A6E]">
                    <span className="font-medium">{t("about.founded")}</span>
                    <br />
                    01/06/2026
                  </p>
                </div>
              </div>

              {/* Content */}
              <div className="space-y-6">
                <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/20 text-[#00E5A0] text-sm font-semibold">
                  {t("about.tag")}
                </span>
                <h2 className="text-4xl md:text-5xl font-bold text-white">
                  {t("about.title")}
                  <br />
                  {t("about.subtitle")}
                </h2>
                <p className="text-lg text-[#94A3B8] leading-relaxed">
                  {t("about.description")}
                </p>
                <div className="flex flex-wrap gap-4">
                  <Link
                    to="/about"
                    className="btn-primary"
                    data-testid="about-learn-more"
                  >
                    {t("about.learnMore")}
                    <ArrowRight className="w-5 h-5 ml-2 inline" />
                  </Link>
                  <Link
                    to="/contacts"
                    className="btn-glass text-white"
                    data-testid="about-questions"
                  >
                    <Phone className="w-5 h-5 mr-2 inline" />
                    {t("about.questions")}
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </section>
      </div>
  );
};

// Need to import Phone for About section
import { Phone } from "lucide-react";

export default HomePage;
