import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { MapPin, Phone, Mail, Clock, Send, MessageSquare } from 'lucide-react';
import { toast } from 'sonner';
import axios from 'axios';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
const API = `${BACKEND_URL}/api`;

const ContactsPage = () => {
  const { t } = useTranslation();
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: ''
  });
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);

    try {
      await axios.post(`${API}/contact`, formData);
      toast.success('Сообщение отправлено! Мы свяжемся с вами в ближайшее время.');
      setFormData({ name: '', email: '', phone: '', message: '' });
    } catch (error) {
      toast.error('Ошибка при отправке сообщения');
    } finally {
      setSubmitting(false);
    }
  };

  const contactInfo = [
    {
      icon: MapPin,
      title: t('contacts.address'),
      value: t('contacts.addressValue'),
      link: 'https://maps.google.com/?q=Минск+ул+Примерная+123'
    },
    {
      icon: Phone,
      title: t('contacts.phone'),
      value: t('contacts.phoneValue'),
      link: 'tel:+375291234567'
    },
    {
      icon: Mail,
      title: t('contacts.email'),
      value: t('contacts.emailValue'),
      link: 'mailto:info@bio-code.by'
    },
    {
      icon: Clock,
      title: t('contacts.workHours'),
      value: t('contacts.workHoursValue'),
      link: null
    }
  ];

  return (
    <div className="min-h-screen pt-20" data-testid="contacts-page">
      {/* Hero Section */}
      <section className="py-20 section-alt" data-testid="contacts-hero">
        <div className="container">
          <div className="max-w-4xl mx-auto text-center">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-6">
              Связаться с нами
            </span>
            <h1 className="text-4xl md:text-6xl font-bold mb-6">{t('contacts.title')}</h1>
            <p className="text-lg text-[#4A5A6E] leading-relaxed">
              {t('contacts.subtitle')}
            </p>
          </div>
        </div>
      </section>

      {/* Contact Cards */}
      <section className="py-16 section-light" data-testid="contact-info-section">
        <div className="container">
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6 mb-16">
            {contactInfo.map((info, index) => {
              const Icon = info.icon;
              const content = (
                <div className="glass-card p-6 text-center h-full service-card" data-testid={`contact-card-${index}`}>
                  <div className="w-14 h-14 mx-auto rounded-2xl bg-[#00E5A0]/10 flex items-center justify-center mb-4">
                    <Icon className="w-7 h-7 text-[#00E5A0]" />
                  </div>
                  <h3 className="font-semibold text-[#1E2A3A] mb-2">{info.title}</h3>
                  <p className="text-[#4A5A6E] text-sm whitespace-pre-line">{info.value}</p>
                </div>
              );

              return info.link ? (
                <a
                  key={index}
                  href={info.link}
                  target={info.link.startsWith('http') ? '_blank' : undefined}
                  rel={info.link.startsWith('http') ? 'noopener noreferrer' : undefined}
                  className="block"
                >
                  {content}
                </a>
              ) : (
                <div key={index}>{content}</div>
              );
            })}
          </div>

          {/* Contact Form & Map */}
          <div className="grid lg:grid-cols-2 gap-12">
            {/* Contact Form */}
            <div className="glass-card p-8" data-testid="contact-form">
              <div className="flex items-center gap-3 mb-6">
                <MessageSquare className="w-6 h-6 text-[#00E5A0]" />
                <h2 className="text-2xl font-bold">{t('contacts.sendMessage')}</h2>
              </div>

              <form onSubmit={handleSubmit} className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                    {t('contacts.name')} *
                  </label>
                  <input
                    type="text"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    className="input-field"
                    required
                    data-testid="contact-name"
                  />
                </div>

                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                      Email *
                    </label>
                    <input
                      type="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      className="input-field"
                      required
                      data-testid="contact-email"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                      {t('contacts.phone')}
                    </label>
                    <input
                      type="tel"
                      value={formData.phone}
                      onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                      className="input-field"
                      data-testid="contact-phone"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                    {t('contacts.message')} *
                  </label>
                  <textarea
                    value={formData.message}
                    onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                    className="textarea-field"
                    rows={5}
                    required
                    data-testid="contact-message"
                  />
                </div>

                <button
                  type="submit"
                  disabled={submitting}
                  className="btn-primary w-full flex items-center justify-center gap-2"
                  data-testid="contact-submit"
                >
                  {submitting ? 'Отправка...' : t('contacts.send')}
                  <Send className="w-5 h-5" />
                </button>
              </form>
            </div>

            {/* Google Maps */}
            <div className="glass-card p-4 overflow-hidden" data-testid="map-container">
              <div className="relative w-full h-full min-h-[400px] rounded-xl overflow-hidden">
                <iframe
                  title="Bio-Code location in Minsk"
                  src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2350.7527617298217!2d27.56161997629776!3d53.90270397361818!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46dbcfd35b1e6dd3%3A0xb61b2ddffe1fe4!2z0JzQuNC90YHQuiDQn9GA0LjQvNC10YDQvdCw0Y8g0YPQuy4sIDEyMywg0JzQuNC90YHQug!5e0!3m2!1sru!2sby!4v1700000000000!5m2!1sru!2sby"
                  width="100%"
                  height="100%"
                  style={{ border: 0, position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}
                  allowFullScreen
                  loading="lazy"
                  referrerPolicy="no-referrer-when-downgrade"
                ></iframe>
                
                {/* Address overlay */}
                <div className="absolute bottom-4 left-4 glass-card p-3 flex items-center gap-2 z-10">
                  <MapPin className="w-5 h-5 text-[#00E5A0]" />
                  <span className="text-sm font-medium text-[#1E2A3A]">{t('contacts.addressValue')}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Quick Actions */}
      <section className="py-16 section-dark" data-testid="quick-actions">
        <div className="container">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold text-white mb-4">Быстрая связь</h2>
            <p className="text-[#94A3B8]">Выберите удобный способ связи</p>
          </div>

          <div className="grid md:grid-cols-3 gap-6 max-w-3xl mx-auto">
            <a
              href="tel:+375291234567"
              className="glass-card-dark p-6 text-center service-card"
              data-testid="quick-call"
            >
              <Phone className="w-8 h-8 text-[#00E5A0] mx-auto mb-3" />
              <p className="text-white font-semibold">Позвонить</p>
            </a>
            
            <a
              href="https://t.me/biocode"
              target="_blank"
              rel="noopener noreferrer"
              className="glass-card-dark p-6 text-center service-card"
              data-testid="quick-telegram"
            >
              <svg className="w-8 h-8 text-[#00E5A0] mx-auto mb-3" fill="currentColor" viewBox="0 0 24 24">
                <path d="M11.944 0A12 12 0 0 0 0 12a12 12 0 0 0 12 12 12 12 0 0 0 12-12A12 12 0 0 0 12 0a12 12 0 0 0-.056 0zm4.962 7.224c.1-.002.321.023.465.14a.506.506 0 0 1 .171.325c.016.093.036.306.02.472-.18 1.898-.962 6.502-1.36 8.627-.168.9-.499 1.201-.82 1.23-.696.065-1.225-.46-1.9-.902-1.056-.693-1.653-1.124-2.678-1.8-1.185-.78-.417-1.21.258-1.91.177-.184 3.247-2.977 3.307-3.23.007-.032.014-.15-.056-.212s-.174-.041-.249-.024c-.106.024-1.793 1.14-5.061 3.345-.48.33-.913.49-1.302.48-.428-.008-1.252-.241-1.865-.44-.752-.245-1.349-.374-1.297-.789.027-.216.325-.437.893-.663 3.498-1.524 5.83-2.529 6.998-3.014 3.332-1.386 4.025-1.627 4.476-1.635z"/>
              </svg>
              <p className="text-white font-semibold">Telegram</p>
            </a>
            
            <a
              href="mailto:info@bio-code.by"
              className="glass-card-dark p-6 text-center service-card"
              data-testid="quick-email"
            >
              <Mail className="w-8 h-8 text-[#00E5A0] mx-auto mb-3" />
              <p className="text-white font-semibold">Email</p>
            </a>
          </div>
        </div>
      </section>
    </div>
  );
};

export default ContactsPage;