import { useTranslation } from 'react-i18next';
import { Award, Shield, CheckCircle, FileCheck, Globe, Building } from 'lucide-react';

const CertificatesPage = () => {
  const { t } = useTranslation();

  const certificates = [
    {
      icon: Award,
      title: t('certificates.iso'),
      subtitle: t('certificates.isoDesc'),
      description: 'Международный стандарт качества для медицинских лабораторий. Подтверждает компетентность и способность производить точные результаты.',
      year: '2025',
      image: 'https://pravotorik.github.io/bio-code/img/laboratory.jpg'
    },
    {
      icon: Globe,
      title: t('certificates.cap'),
      subtitle: t('certificates.capDesc'),
      description: 'Аккредитация Колледжа Американских Патологов — золотой стандарт качества лабораторной диагностики в мире.',
      year: '2026',
      image: 'https://pravotorik.github.io/bio-code/img/accredit.jpg'
    },
    {
      icon: Building,
      title: t('certificates.ministry'),
      subtitle: t('certificates.ministryDesc'),
      description: 'Государственная лицензия на осуществление медицинской деятельности на территории Республики Беларусь.',
      year: '2026',
      image: 'https://pravotorik.github.io/bio-code/img/minzdrav.webp'
    },
  ];

  const achievements = [
    { icon: Shield, title: 'ISO 9001:2015', desc: 'Система менеджмента качества' },
    { icon: FileCheck, title: 'GCLP', desc: 'Надлежащая клиническая лабораторная практика' },
    { icon: CheckCircle, title: 'CE IVD', desc: 'Европейский сертификат на оборудование' },
    { icon: Award, title: 'EQA', desc: 'Участие в программах внешней оценки качества' },
  ];

  return (
    <div className="min-h-screen pt-20" data-testid="certificates-page">
      {/* Hero Section */}
      <section className="py-20 section-alt" data-testid="certificates-hero">
        <div className="container">
          <div className="max-w-4xl mx-auto text-center">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-6">
              Качество
            </span>
            <h1 className="text-4xl md:text-6xl font-bold mb-6">{t('certificates.title')}</h1>
            <p className="text-lg text-[#4A5A6E] leading-relaxed">
              {t('certificates.subtitle')}
            </p>
          </div>
        </div>
      </section>

      {/* Main Certificates */}
      <section className="py-20 section-light" data-testid="certificates-main">
        <div className="container">
          <div className="space-y-16">
            {certificates.map((cert, index) => {
              const Icon = cert.icon;
              const isEven = index % 2 === 0;
              
              return (
                <div
                  key={index}
                  className={`grid lg:grid-cols-2 gap-12 items-center ${!isEven ? 'lg:flex-row-reverse' : ''}`}
                  data-testid={`certificate-${index}`}
                >
                  <div className={`${!isEven ? 'lg:order-2' : ''}`}>
                    <div className="glass-card p-4 overflow-hidden">
                      <img
                        src={cert.image}
                        alt={cert.title}
                        className="w-full h-[300px] object-cover rounded-2xl"
                      />
                    </div>
                  </div>
                  
                  <div className={`space-y-6 ${!isEven ? 'lg:order-1' : ''}`}>
                    <div className="inline-flex items-center gap-3">
                      <div className="w-14 h-14 rounded-2xl bg-[#00E5A0]/10 flex items-center justify-center">
                        <Icon className="w-7 h-7 text-[#00E5A0]" />
                      </div>
                      <span className="text-sm font-semibold text-[#00E5A0]">С {cert.year} года</span>
                    </div>
                    
                    <h2 className="text-3xl font-bold text-[#1E2A3A]">{cert.title}</h2>
                    <p className="text-xl text-[#4A5A6E]">{cert.subtitle}</p>
                    <p className="text-[#4A5A6E] leading-relaxed">{cert.description}</p>
                    
                    <div className="flex items-center gap-2 text-[#00E5A0]">
                      <CheckCircle className="w-5 h-5" />
                      <span className="font-medium">Действующий сертификат</span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Additional Achievements */}
      <section className="py-20 section-dark" data-testid="achievements-section">
        <div className="container">
          <div className="text-center mb-16">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/20 text-[#00E5A0] text-sm font-semibold mb-4">
              Достижения
            </span>
            <h2 className="text-3xl md:text-4xl font-bold text-white">
              Дополнительные стандарты качества
            </h2>
          </div>

          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">
            {achievements.map((item, index) => {
              const Icon = item.icon;
              return (
                <div
                  key={index}
                  className="glass-card-dark p-6 text-center service-card"
                  data-testid={`achievement-${index}`}
                >
                  <div className="w-16 h-16 mx-auto rounded-2xl bg-[#00E5A0]/10 flex items-center justify-center mb-4">
                    <Icon className="w-8 h-8 text-[#00E5A0]" />
                  </div>
                  <h3 className="text-xl font-semibold text-white mb-2">{item.title}</h3>
                  <p className="text-[#94A3B8] text-sm">{item.desc}</p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Trust Section */}
      <section className="py-20 section-alt" data-testid="trust-section">
        <div className="container">
          <div className="glass-card p-12 max-w-4xl mx-auto">
            <div className="text-center">
              <Shield className="w-16 h-16 text-[#00E5A0] mx-auto mb-6" />
              <h2 className="text-3xl font-bold mb-4">Гарантия качества</h2>
              <p className="text-lg text-[#4A5A6E] leading-relaxed mb-8">
                Все наши исследования проводятся на современном оборудовании ведущих мировых производителей.
                Мы регулярно проходим внешний контроль качества и подтверждаем соответствие международным стандартам.
              </p>
              <div className="flex flex-wrap justify-center gap-6">
                <div className="text-center">
                  <p className="text-4xl font-bold text-[#00E5A0]">98%</p>
                  <p className="text-sm text-[#4A5A6E]">Точность результатов</p>
                </div>
                <div className="text-center">
                  <p className="text-4xl font-bold text-[#00E5A0]">24ч</p>
                  <p className="text-sm text-[#4A5A6E]">Срок выполнения</p>
                </div>
                <div className="text-center">
                  <p className="text-4xl font-bold text-[#00E5A0]">1</p>
                  <p className="text-sm text-[#4A5A6E]">Персональный подход</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};
export default CertificatesPage;