import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import { 
  Dna, Droplet, Clock, Users, Pill, Activity, Heart, Brain, 
  Eye, Bone, Baby, Stethoscope, Microscope, TestTube, 
  ArrowRight, Search, Filter
} from 'lucide-react';

const ServicesPage = () => {
  const { t } = useTranslation();
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('all');

  const categories = [
    { id: 'all', label: 'Все услуги' },
    { id: 'genetic', label: 'Генетика' },
    { id: 'blood', label: 'Анализы крови' },
    { id: 'hormones', label: 'Гормоны' },
    { id: 'other', label: 'Другие' },
  ];

  const services = [
    // Genetic
    { id: 1, icon: Dna, title: 'Полный геном', desc: 'Секвенирование всего генома для глубокого анализа', price: 'от 2500 BYN', category: 'genetic', popular: true },
    { id: 2, icon: Dna, title: 'Экзом', desc: 'Анализ кодирующих участков генов', price: 'от 1800 BYN', category: 'genetic' },
    { id: 3, icon: Users, title: 'ДНК на родство', desc: 'Установление биологического родства', price: 'от 450 BYN', category: 'genetic', popular: true },
    { id: 4, icon: Dna, title: 'Наследственные заболевания', desc: 'Скрининг на 300+ наследственных патологий', price: 'от 900 BYN', category: 'genetic' },
    { id: 5, icon: Baby, title: 'Пренатальный скрининг', desc: 'Неинвазивный тест для беременных', price: 'от 650 BYN', category: 'genetic' },
    
    // Blood
    { id: 6, icon: Droplet, title: 'Общий анализ крови', desc: 'Базовое исследование состава крови', price: 'от 25 BYN', category: 'blood' },
    { id: 7, icon: Droplet, title: 'Биохимия расширенная', desc: '30+ показателей работы органов', price: 'от 120 BYN', category: 'blood', popular: true },
    { id: 8, icon: TestTube, title: 'Липидный профиль', desc: 'Холестерин и фракции', price: 'от 45 BYN', category: 'blood' },
    { id: 9, icon: Heart, title: 'Кардиомаркеры', desc: 'Оценка риска сердечно-сосудистых заболеваний', price: 'от 180 BYN', category: 'blood' },
    { id: 10, icon: Microscope, title: 'Коагулограмма', desc: 'Анализ свёртываемости крови', price: 'от 55 BYN', category: 'blood' },
    
    // Hormones
    { id: 11, icon: Activity, title: 'Щитовидная железа', desc: 'ТТГ, Т3, Т4, антитела', price: 'от 85 BYN', category: 'hormones', popular: true },
    { id: 12, icon: Activity, title: 'Половые гормоны (муж)', desc: 'Тестостерон, ГСПГ, ЛГ, ФСГ', price: 'от 110 BYN', category: 'hormones' },
    { id: 13, icon: Activity, title: 'Половые гормоны (жен)', desc: 'Эстрадиол, прогестерон, пролактин', price: 'от 130 BYN', category: 'hormones' },
    { id: 14, icon: Activity, title: 'Надпочечники', desc: 'Кортизол, ДГЭА-С, альдостерон', price: 'от 95 BYN', category: 'hormones' },
    { id: 15, icon: Activity, title: 'Инсулинорезистентность', desc: 'Глюкоза, инсулин, HOMA-IR', price: 'от 65 BYN', category: 'hormones' },
    
    // Other
    { id: 16, icon: Clock, title: 'Био-возраст', desc: 'Определение биологического возраста организма', price: 'от 350 BYN', category: 'other', popular: true },
    { id: 17, icon: Pill, title: 'Нутригенетика', desc: 'Подбор питания по генетике', price: 'от 480 BYN', category: 'other' },
    { id: 18, icon: Stethoscope, title: 'Микробиом кишечника', desc: 'Анализ микрофлоры', price: 'от 280 BYN', category: 'other' },
    { id: 19, icon: Brain, title: 'Нейромедиаторы', desc: 'Дофамин, серотонин, норадреналин', price: 'от 220 BYN', category: 'other' },
    { id: 20, icon: Eye, title: 'Витамины и минералы', desc: 'Комплексный анализ 25 показателей', price: 'от 190 BYN', category: 'other' },
    { id: 21, icon: Bone, title: 'Маркеры костной ткани', desc: 'Остеопороз и метаболизм кальция', price: 'от 140 BYN', category: 'other' },
  ];

  const filteredServices = services.filter(service => {
    const matchesSearch = service.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         service.desc.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = activeCategory === 'all' || service.category === activeCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="min-h-screen pt-20" data-testid="services-page">
      {/* Hero Section */}
      <section className="py-20 section-alt" data-testid="services-hero">
        <div className="container">
          <div className="max-w-4xl mx-auto text-center">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-6">
              {t('services.title')}
            </span>
            <h1 className="text-4xl md:text-6xl font-bold mb-6">{t('services.title')}</h1>
            <p className="text-lg text-[#4A5A6E] leading-relaxed">
              {t('services.subtitle')}
            </p>
          </div>
        </div>
      </section>

      {/* Search & Filter */}
      <section className="py-8 section-light border-b border-[#E0E7F0]" data-testid="services-filter">
        <div className="container">
          <div className="flex flex-col md:flex-row gap-6 items-center justify-between">
            {/* Search */}
            <div className="relative w-full md:w-96">
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 w-5 h-5 text-[#94A3B8]" />
              <input
                type="text"
                placeholder="Поиск услуг..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="input-field pl-12"
                data-testid="services-search"
              />
            </div>

            {/* Categories */}
            <div className="flex flex-wrap gap-2">
              {categories.map((cat) => (
                <button
                  key={cat.id}
                  onClick={() => setActiveCategory(cat.id)}
                  className={`px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${
                    activeCategory === cat.id
                      ? 'bg-[#00E5A0] text-[#0A1F44]'
                      : 'bg-white border border-[#E0E7F0] text-[#4A5A6E] hover:border-[#00E5A0]'
                  }`}
                  data-testid={`category-${cat.id}`}
                >
                  {cat.label}
                </button>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Services Grid */}
      <section className="py-16 section-light" data-testid="services-grid">
        <div className="container">
          {filteredServices.length === 0 ? (
            <div className="text-center py-16">
              <p className="text-lg text-[#4A5A6E]">Услуги не найдены</p>
            </div>
          ) : (
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredServices.map((service) => {
                const Icon = service.icon;
                return (
                  <div
                    key={service.id}
                    className="service-card glass-card p-6 group relative"
                    data-testid={`service-item-${service.id}`}
                  >
                    {service.popular && (
                      <span className="absolute top-4 right-4 px-3 py-1 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-xs font-semibold">
                        Популярно
                      </span>
                    )}
                    
                    <div className="w-12 h-12 rounded-xl bg-[#00E5A0]/10 flex items-center justify-center mb-4 group-hover:bg-[#00E5A0]/20 transition-colors duration-300">
                      <Icon className="w-6 h-6 text-[#00E5A0]" />
                    </div>
                    
                    <h3 className="text-lg font-semibold text-[#1E2A3A] mb-2">{service.title}</h3>
                    <p className="text-sm text-[#4A5A6E] mb-4">{service.desc}</p>
                    
                    <div className="flex items-center justify-between">
                      <span className="text-lg font-bold text-[#00E5A0]">{service.price}</span>
                      <Link
                        to="/appointment"
                        className="flex items-center gap-1 text-sm text-[#4A5A6E] hover:text-[#00E5A0] transition-colors duration-300"
                      >
                        Записаться
                        <ArrowRight className="w-4 h-4" />
                      </Link>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-20 section-dark" data-testid="services-cta">
        <div className="container">
          <div className="max-w-3xl mx-auto text-center">
            <h2 className="text-3xl md:text-4xl font-bold text-white mb-6">
              Не нашли нужный анализ?
            </h2>
            <p className="text-lg text-[#94A3B8] mb-8">
              Свяжитесь с нами, и мы поможем подобрать оптимальный комплекс исследований
            </p>
            <div className="flex flex-wrap gap-4 justify-center">
              <Link to="/contacts" className="btn-primary" data-testid="services-contact-btn">
                Связаться с нами
              </Link>
              <Link to="/appointment" className="btn-glass text-white" data-testid="services-appointment-btn">
                Записаться на прием
              </Link>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};
export default ServicesPage;