import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

const ScrollToTop = () => {
  const { pathname, hash } = useLocation();

  useEffect(() => {
    // Если есть якорь (например #section), прокручиваем к элементу
    if (hash) {
      const element = document.querySelector(hash);
      if (element) {
        setTimeout(() => {
          element.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      }
    } else {
      // Иначе в самый верх страницы
      window.scrollTo({
        top: 0,
        left: 0,
        behavior: 'auto' // 'auto' для мгновенной прокрутки или 'smooth' для плавной
      });
    }
  }, [pathname, hash]); // Срабатывает при изменении пути или якоря

  return null;
};

export default ScrollToTop;