import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { MessageSquare, Plus, User, Clock, ChevronRight, Send, ArrowLeft } from 'lucide-react';
import { toast } from 'sonner';
import axios from 'axios';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
const API = `${BACKEND_URL}/api`;

const ForumPage = () => {
  const { t } = useTranslation();
  const [topics, setTopics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showNewTopicForm, setShowNewTopicForm] = useState(false);
  const [selectedTopic, setSelectedTopic] = useState(null);
  const [newTopic, setNewTopic] = useState({ title: '', author: '', content: '' });
  const [newReply, setNewReply] = useState({ author: '', content: '' });
  const [submitting, setSubmitting] = useState(false);

  // Sample topics
  const sampleTopics = [
    {
      id: 1,
      title: 'Вопросы по генетическому анализу',
      author: 'Анна М.',
      content: 'Добрый день! Подскажите, сколько времени занимает полный генетический анализ и что он включает?',
      date: '2024-12-18',
      replies: [
        { id: 1, author: 'Dr. Иванова', content: 'Здравствуйте! Полный генетический анализ занимает 2-3 недели. Включает секвенирование генома и детальную интерпретацию.', date: '2024-12-18' },
        { id: 2, author: 'Модератор', content: 'Также вы можете записаться на бесплатную консультацию для уточнения всех деталей.', date: '2024-12-19' }
      ],
      views: 156
    },
    {
      id: 2,
      title: 'Подготовка к сдаче анализов',
      author: 'Сергей К.',
      content: 'Какая подготовка нужна перед сдачей крови на биохимию?',
      date: '2024-12-15',
      replies: [
        { id: 1, author: 'Dr. Петров', content: 'Для биохимического анализа необходимо сдавать кровь натощак (8-12 часов голодания). Можно пить воду.', date: '2024-12-15' }
      ],
      views: 234
    },
    {
      id: 3,
      title: 'Нутригенетика - кто делал?',
      author: 'Елена В.',
      content: 'Интересует опыт прохождения нутригенетического теста. Насколько это помогает в подборе питания?',
      date: '2024-12-10',
      replies: [
        { id: 1, author: 'Ольга С.', content: 'Делала в прошлом году, очень довольна! Узнала много нового о себе и смогла скорректировать рацион.', date: '2024-12-11' },
        { id: 2, author: 'Михаил Н.', content: 'Рекомендую! Особенно полезно, если есть проблемы с весом или пищеварением.', date: '2024-12-12' }
      ],
      views: 312
    },
    {
      id: 4,
      title: 'ДНК-тест на родство',
      author: 'Дмитрий Л.',
      content: 'Вопрос деликатный, но хочу узнать - насколько конфиденциально проходит тест на родство?',
      date: '2024-12-05',
      replies: [
        { id: 1, author: 'Администратор', content: 'Полная конфиденциальность гарантирована. Результаты передаются только заказчику, данные хранятся в зашифрованном виде.', date: '2024-12-05' }
      ],
      views: 189
    },
  ];

  useEffect(() => {
    fetchTopics();
  }, []);

  const fetchTopics = async () => {
    try {
      const response = await axios.get(`${API}/forum/topics`);
      setTopics([...sampleTopics, ...response.data]);
    } catch (error) {
      setTopics(sampleTopics);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTopic = async (e) => {
    e.preventDefault();
    setSubmitting(true);

    try {
      const topicData = {
        ...newTopic,
        date: new Date().toISOString().split('T')[0],
        replies: [],
        views: 0
      };
      
      await axios.post(`${API}/forum/topics`, topicData);
      setTopics([{ ...topicData, id: Date.now() }, ...topics]);
      setNewTopic({ title: '', author: '', content: '' });
      setShowNewTopicForm(false);
      toast.success('Тема успешно создана!');
    } catch (error) {
      toast.error('Ошибка при создании темы');
    } finally {
      setSubmitting(false);
    }
  };

  const handleAddReply = async (e) => {
    e.preventDefault();
    if (!selectedTopic) return;
    setSubmitting(true);

    try {
      const replyData = {
        ...newReply,
        date: new Date().toISOString().split('T')[0],
        id: Date.now()
      };

      const updatedTopics = topics.map(topic => {
        if (topic.id === selectedTopic.id) {
          return { ...topic, replies: [...topic.replies, replyData] };
        }
        return topic;
      });

      setTopics(updatedTopics);
      setSelectedTopic({ ...selectedTopic, replies: [...selectedTopic.replies, replyData] });
      setNewReply({ author: '', content: '' });
      toast.success('Ответ добавлен!');
    } catch (error) {
      toast.error('Ошибка при добавлении ответа');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen pt-20" data-testid="forum-page">
      {/* Hero Section */}
      <section className="py-20 section-alt" data-testid="forum-hero">
        <div className="container">
          <div className="max-w-4xl mx-auto text-center">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-6">
              Сообщество
            </span>
            <h1 className="text-4xl md:text-6xl font-bold mb-6">{t('forum.title')}</h1>
            <p className="text-lg text-[#4A5A6E] leading-relaxed">
              {t('forum.subtitle')}
            </p>
          </div>
        </div>
      </section>

      {/* Forum Content */}
      <section className="py-16 section-light" data-testid="forum-content">
        <div className="container">
          {selectedTopic ? (
            /* Topic Detail View */
            <div className="max-w-4xl mx-auto">
              <button
                onClick={() => setSelectedTopic(null)}
                className="flex items-center gap-2 text-[#4A5A6E] hover:text-[#00E5A0] mb-6 transition-colors duration-300"
                data-testid="back-to-topics"
              >
                <ArrowLeft className="w-5 h-5" />
                Назад к темам
              </button>

              <div className="glass-card p-8 mb-8">
                <h2 className="text-2xl font-bold mb-4">{selectedTopic.title}</h2>
                <div className="flex items-center gap-4 mb-6 text-sm text-[#4A5A6E]">
                  <div className="flex items-center gap-2">
                    <User className="w-4 h-4" />
                    {selectedTopic.author}
                  </div>
                  <div className="flex items-center gap-2">
                    <Clock className="w-4 h-4" />
                    {new Date(selectedTopic.date).toLocaleDateString('ru-RU')}
                  </div>
                </div>
                <p className="text-[#4A5A6E] leading-relaxed">{selectedTopic.content}</p>
              </div>

              {/* Replies */}
              <div className="space-y-4 mb-8">
                <h3 className="text-lg font-semibold">Ответы ({selectedTopic.replies.length})</h3>
                {selectedTopic.replies.map((reply, index) => (
                  <div key={reply.id || index} className="glass-card p-6" data-testid={`reply-${index}`}>
                    <div className="flex items-center gap-3 mb-3">
                      <div className="w-10 h-10 rounded-full bg-[#00E5A0]/10 flex items-center justify-center">
                        <User className="w-5 h-5 text-[#00E5A0]" />
                      </div>
                      <div>
                        <p className="font-semibold text-[#1E2A3A]">{reply.author}</p>
                        <p className="text-xs text-[#94A3B8]">
                          {new Date(reply.date).toLocaleDateString('ru-RU')}
                        </p>
                      </div>
                    </div>
                    <p className="text-[#4A5A6E] pl-13">{reply.content}</p>
                  </div>
                ))}
              </div>

              {/* Add Reply Form */}
              <div className="glass-card p-6">
                <h3 className="text-lg font-semibold mb-4">Добавить ответ</h3>
                <form onSubmit={handleAddReply} className="space-y-4">
                  <input
                    type="text"
                    placeholder="Ваше имя"
                    value={newReply.author}
                    onChange={(e) => setNewReply({ ...newReply, author: e.target.value })}
                    className="input-field"
                    required
                    data-testid="reply-author-input"
                  />
                  <textarea
                    placeholder="Ваш ответ..."
                    value={newReply.content}
                    onChange={(e) => setNewReply({ ...newReply, content: e.target.value })}
                    className="textarea-field"
                    rows={3}
                    required
                    data-testid="reply-content-input"
                  />
                  <button
                    type="submit"
                    disabled={submitting}
                    className="btn-primary flex items-center gap-2"
                    data-testid="reply-submit-btn"
                  >
                    <Send className="w-5 h-5" />
                    Отправить
                  </button>
                </form>
              </div>
            </div>
          ) : (
            /* Topics List View */
            <div className="max-w-4xl mx-auto">
              {/* New Topic Button */}
              <div className="flex justify-between items-center mb-8">
                <h2 className="text-2xl font-bold">{t('forum.topics')}</h2>
                <button
                  onClick={() => setShowNewTopicForm(!showNewTopicForm)}
                  className="btn-primary flex items-center gap-2"
                  data-testid="new-topic-btn"
                >
                  <Plus className="w-5 h-5" />
                  {t('forum.newTopic')}
                </button>
              </div>

              {/* New Topic Form */}
              {showNewTopicForm && (
                <div className="glass-card p-6 mb-8" data-testid="new-topic-form">
                  <h3 className="text-lg font-semibold mb-4">Создать новую тему</h3>
                  <form onSubmit={handleCreateTopic} className="space-y-4">
                    <input
                      type="text"
                      placeholder="Заголовок темы"
                      value={newTopic.title}
                      onChange={(e) => setNewTopic({ ...newTopic, title: e.target.value })}
                      className="input-field"
                      required
                      data-testid="topic-title-input"
                    />
                    <input
                      type="text"
                      placeholder="Ваше имя"
                      value={newTopic.author}
                      onChange={(e) => setNewTopic({ ...newTopic, author: e.target.value })}
                      className="input-field"
                      required
                      data-testid="topic-author-input"
                    />
                    <textarea
                      placeholder="Содержание..."
                      value={newTopic.content}
                      onChange={(e) => setNewTopic({ ...newTopic, content: e.target.value })}
                      className="textarea-field"
                      rows={4}
                      required
                      data-testid="topic-content-input"
                    />
                    <div className="flex gap-4">
                      <button
                        type="submit"
                        disabled={submitting}
                        className="btn-primary"
                        data-testid="topic-submit-btn"
                      >
                        Создать тему
                      </button>
                      <button
                        type="button"
                        onClick={() => setShowNewTopicForm(false)}
                        className="btn-secondary"
                      >
                        Отмена
                      </button>
                    </div>
                  </form>
                </div>
              )}

              {/* Topics List */}
              <div className="space-y-4">
                {topics.map((topic, index) => (
                  <div
                    key={topic.id}
                    className="glass-card p-6 service-card cursor-pointer"
                    onClick={() => setSelectedTopic(topic)}
                    data-testid={`topic-${index}`}
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <h3 className="text-lg font-semibold text-[#1E2A3A] mb-2 hover:text-[#00E5A0] transition-colors duration-300">
                          {topic.title}
                        </h3>
                        <div className="flex items-center gap-4 text-sm text-[#4A5A6E]">
                          <div className="flex items-center gap-1">
                            <User className="w-4 h-4" />
                            {topic.author}
                          </div>
                          <div className="flex items-center gap-1">
                            <Clock className="w-4 h-4" />
                            {new Date(topic.date).toLocaleDateString('ru-RU')}
                          </div>
                          <div className="flex items-center gap-1">
                            <MessageSquare className="w-4 h-4" />
                            {topic.replies.length} {t('forum.replies')}
                          </div>
                        </div>
                      </div>
                      <ChevronRight className="w-5 h-5 text-[#94A3B8]" />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </section>
    </div>
  );
};
export default ForumPage;