import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Menu, X, ChevronDown } from 'lucide-react';

export const Header = () => {
  const { t, i18n } = useTranslation();
  const location = useLocation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [langDropdownOpen, setLangDropdownOpen] = useState(false);

  const navLinks = [
    { path: '/', label: t('nav.home') },
    { path: '/about', label: t('nav.about') },
    { path: '/services', label: t('nav.services') },
    { path: '/certificates', label: t('nav.certificates') },
    { path: '/reviews', label: t('nav.reviews') },
    { path: '/forum', label: t('nav.forum') },
    { path: '/appointment', label: t('nav.appointment') },
    { path: '/contacts', label: t('nav.contacts') },
  ];

  const languages = [
    { code: 'ru', label: 'RU' },
    { code: 'en', label: 'EN' },
    { code: 'by', label: 'BY' },
  ];

  const changeLanguage = (langCode) => {
    i18n.changeLanguage(langCode);
    setLangDropdownOpen(false);
  };

  const currentLang = languages.find(l => l.code === i18n.language) || languages[0];

  return (
    <header className="fixed top-0 left-0 right-0 z-50 glass-nav" data-testid="header">
      <div className="container">
        <div className="flex items-center justify-between h-20">
          {/* Logo */}
          <Link to="/" className="flex items-center gap-2" data-testid="logo-link">
            <span className="text-2xl font-extrabold tracking-tight" style={{ fontFamily: 'Manrope, sans-serif' }}>
              <span style={{ color: '#0A1F44' }}>BIO</span>
              <span style={{ color: '#00E5A0' }}>-CODE</span>
            </span>
          </Link>

          {/* Desktop Navigation */}
          <nav className="hidden lg:flex items-center gap-8" data-testid="desktop-nav">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`nav-link text-sm font-medium ${
                  location.pathname === link.path ? 'active' : ''
                }`}
                data-testid={`nav-link-${link.path.replace('/', '') || 'home'}`}
              >
                {link.label}
              </Link>
            ))}
          </nav>

          {/* Language Switcher + CTA */}
          <div className="hidden lg:flex items-center gap-4">
            {/* Language Dropdown */}
            <div className="relative">
              <button
                onClick={() => setLangDropdownOpen(!langDropdownOpen)}
                className="flex items-center gap-1 px-3 py-2 text-sm font-medium text-[#4A5A6E] hover:text-[#00E5A0] transition-colors duration-300"
                data-testid="lang-dropdown-btn"
              >
                {currentLang.label}
                <ChevronDown className="w-4 h-4" />
              </button>
              
              {langDropdownOpen && (
                <div className="absolute top-full right-0 mt-2 glass-card py-2 min-w-[80px]" data-testid="lang-dropdown-menu">
                  {languages.map((lang) => (
                    <button
                      key={lang.code}
                      onClick={() => changeLanguage(lang.code)}
                      className={`w-full px-4 py-2 text-left text-sm hover:bg-[#00E5A0]/10 transition-colors duration-300 ${
                        i18n.language === lang.code ? 'text-[#00E5A0] font-semibold' : 'text-[#4A5A6E]'
                      }`}
                      data-testid={`lang-option-${lang.code}`}
                    >
                      {lang.label}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* CTA Button */}
            <Link to="/appointment" className="btn-primary text-sm px-6 py-3" data-testid="header-cta">
              {t('nav.appointment')}
            </Link>
          </div>

          {/* Mobile Menu Button */}
          <button
            className="lg:hidden p-2"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            data-testid="mobile-menu-btn"
          >
            {mobileMenuOpen ? (
              <X className="w-6 h-6 text-[#1E2A3A]" />
            ) : (
              <Menu className="w-6 h-6 text-[#1E2A3A]" />
            )}
          </button>
        </div>

        {/* Mobile Menu */}
        {mobileMenuOpen && (
          <div className="lg:hidden glass-card absolute top-20 left-4 right-4 p-6" data-testid="mobile-menu">
            <nav className="flex flex-col gap-4">
              {navLinks.map((link) => (
                <Link
                  key={link.path}
                  to={link.path}
                  onClick={() => setMobileMenuOpen(false)}
                  className={`text-base font-medium py-2 ${
                    location.pathname === link.path ? 'text-[#00E5A0]' : 'text-[#1E2A3A]'
                  }`}
                  data-testid={`mobile-nav-link-${link.path.replace('/', '') || 'home'}`}
                >
                  {link.label}
                </Link>
              ))}
            </nav>
            
            {/* Mobile Language Switcher */}
            <div className="flex gap-2 mt-6 pt-6 border-t border-[#E0E7F0]">
              {languages.map((lang) => (
                <button
                  key={lang.code}
                  onClick={() => changeLanguage(lang.code)}
                  className={`lang-btn ${i18n.language === lang.code ? 'active' : ''}`}
                  data-testid={`mobile-lang-${lang.code}`}
                >
                  {lang.label}
                </button>
              ))}
            </div>

            <Link
              to="/appointment"
              onClick={() => setMobileMenuOpen(false)}
              className="btn-primary w-full text-center mt-4"
              data-testid="mobile-cta"
            >
              {t('nav.appointment')}
            </Link>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
