import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import { Award, Users, Target, Clock, ArrowRight, CheckCircle, Heart } from 'lucide-react';

const AboutPage = () => {
  const { t } = useTranslation();

  const timeline = [
    { year: '2025', event: t('history.2025') },
    { year: '2026', event: t('history.2026') },
    { year: '2027', event: t('history.2027') },
    { year: '2028', event: t('history.2028') },
    { year: '2029', event: t('history.2029') },
    { year: '2030', event: t('history.2030') }, // Исправлено
  ];

  const team = [
    {
      name: t('team.doctor1.name'),
      role: t('team.doctor1.role'),
      exp: t('team.doctor1.exp'),
      image: 'https://pravotorik.github.io/bio-code/img/doc1.jpg'
    },
    {
      name: t('team.doctor2.name'),
      role: t('team.doctor2.role'),
      exp: t('team.doctor2.exp'),
      image: 'https://pravotorik.github.io/bio-code/img/doc2.jpg'
    },
    {
      name: t('team.doctor3.name'),
      role: t('team.doctor3.role'),
      exp: t('team.doctor3.exp'),
      image: 'https://pravotorik.github.io/bio-code/img/doc3.jpg'
    },
  ];

  const values = [
    { icon: Award, title: 'Качество', desc: 'Международные стандарты ISO 15189' },
    { icon: Users, title: 'Забота', desc: 'Индивидуальный подход к каждому' },
    { icon: Target, title: 'Точность', desc: '98% точность диагностики' },
    { icon: Clock, title: 'Скорость', desc: 'Результаты в кратчайшие сроки' },
  ];

  return (
    <div className="min-h-screen pt-20" data-testid="about-page">
      {/* Hero Section */}
      <section className="py-20 section-alt" data-testid="about-hero">
        <div className="container">
          <div className="max-w-4xl mx-auto text-center">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-6">
              {t('about.tag')}
            </span>
            <h1 className="text-4xl md:text-6xl font-bold mb-6">
              {t('about.title')} — {t('about.subtitle')}
            </h1>
            <p className="text-lg text-[#4A5A6E] leading-relaxed">
              {t('about.description')}
            </p>
          </div>
        </div>
      </section>

      {/* Mission Section */}
      <section className="py-20 section-light" data-testid="mission-section">
        <div className="container">
          <div className="grid lg:grid-cols-2 gap-16 items-center">
            {/* Левая колонка с изображением */}
            <div className="relative">
              <div className="glass-card p-4 overflow-hidden">
                <img
                  src="https://pravotorik.github.io/bio-code/img/mission.jpg"
                  alt="Laboratory"
                  className="w-full h-[450px] object-cover rounded-2xl"
                  data-testid="mission-image"
                />
              </div>
              
              {/* Info Card */}
              <div 
                className="absolute -bottom-8 -right-8 glass-card p-6 max-w-[250px] z-10" 
                data-testid="about-info-card"
              >
                <div className="flex items-center gap-3 mb-3">
                  <div className="w-10 h-10 rounded-full bg-[#00E5A0] flex items-center justify-center">
                    <Heart className="w-5 h-5 text-[#0A1F44]" />
                  </div>
                  <span className="font-semibold text-[#1E2A3A]">BIO-CODE</span>
                </div>
                <p className="text-sm text-[#4A5A6E]">
                  <span className="font-medium">{t('about.founded')}</span><br />
                  01/06/2026
                </p>
              </div>
            </div>

            {/* Правая колонка с ценностями */}
            <div>
              <div className="grid grid-cols-2 gap-4">
                {values.map((value, index) => {
                  const Icon = value.icon;
                  return (
                    <div 
                      key={index} 
                      className="glass-card p-4 service-card" 
                      data-testid={`value-card-${index}`}
                    >
                      <Icon className="w-8 h-8 text-[#00E5A0] mb-3" />
                      <h4 className="font-semibold text-[#1E2A3A] mb-1">{value.title}</h4>
                      <p className="text-sm text-[#4A5A6E]">{value.desc}</p>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* History Timeline */}
      <section className="py-20 section-dark" data-testid="history-section">
        <div className="container">
          <div className="text-center mb-16">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/20 text-[#00E5A0] text-sm font-semibold mb-4">
              Перспективы на будущее
            </span>
            <h2 className="text-3xl md:text-4xl font-bold text-white">{t('history.title')}</h2>
          </div>

          <div className="max-w-4xl mx-auto">
            <div className="relative">
              {/* Timeline Line */}
              <div className="absolute left-8 md:left-1/2 top-0 bottom-0 w-px bg-[#00E5A0]/30"></div>

              {timeline.map((item, index) => (
                <div
                  key={index}
                  className={`relative flex items-center gap-8 mb-12 ${
                    index % 2 === 0 ? 'md:flex-row' : 'md:flex-row-reverse'
                  }`}
                  data-testid={`timeline-item-${index}`}
                >
                  {/* Dot */}
                  <div className="absolute left-8 md:left-1/2 w-4 h-4 rounded-full bg-[#00E5A0] transform -translate-x-1/2 z-10"></div>
                  
                  {/* Content */}
                  <div className={`ml-16 md:ml-0 md:w-1/2 ${index % 2 === 0 ? 'md:pr-16 md:text-right' : 'md:pl-16'}`}>
                    <div className="glass-card-dark p-6">
                      <span className="text-2xl font-bold text-[#00E5A0]">{item.year}</span>
                      <p className="text-white mt-2">{item.event}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Team Section */}
      <section className="py-20 section-light" data-testid="team-section">
        <div className="container">
          <div className="text-center mb-16">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-4">
              Команда
            </span>
            <h2 className="text-3xl md:text-4xl font-bold">{t('team.title')}</h2>
          </div>

          <div className="grid md:grid-cols-3 gap-8">
            {team.map((member, index) => (
              <div
                key={index}
                className="glass-card p-6 text-center service-card group"
                data-testid={`team-member-${index}`}
              >
                <div className="w-32 h-32 mx-auto mb-6 rounded-full overflow-hidden border-4 border-[#00E5A0]/20 group-hover:border-[#00E5A0]/50 transition-colors duration-300">
                  <img
                    src={member.image}
                    alt={member.name}
                    className="w-full h-full object-cover"
                  />
                </div>
                <h3 className="text-xl font-semibold text-[#1E2A3A] mb-2">{member.name}</h3>
                <p className="text-[#00E5A0] font-medium mb-2">{member.role}</p>
                <p className="text-sm text-[#4A5A6E]">{member.exp}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-20 section-alt" data-testid="cta-section">
        <div className="container">
          <div className="glass-card p-12 text-center max-w-3xl mx-auto">
            <h2 className="text-3xl font-bold mb-4">Готовы начать?</h2>
            <p className="text-lg text-[#4A5A6E] mb-8">
              Запишитесь на консультацию и узнайте больше о своём здоровье
            </p>
            <Link to="/appointment" className="btn-primary inline-flex items-center gap-2" data-testid="about-cta">
              {t('hero.ctaSecondary')}
              <ArrowRight className="w-5 h-5" />
            </Link>
          </div>
        </div>
      </section>
    </div>
  );
};

export default AboutPage;