import { useState } from "react";
import { useTranslation } from "react-i18next";
import {
  Calendar as CalendarIcon,
  Clock,
  User,
  Phone,
  Mail,
  FileText,
  CheckCircle,
} from "lucide-react";
import { toast } from "sonner";
import axios from "axios";
import { DayPicker } from "react-day-picker";
import "react-day-picker/dist/style.css";

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
const API = `${BACKEND_URL}/api`;

const AppointmentPage = () => {
  const { t } = useTranslation();
  const [step, setStep] = useState(1);
  const [date, setDate] = useState(undefined);
  const [formData, setFormData] = useState({
    service: "",
    doctor: "",
    time: "",
    name: "",
    phone: "",
    email: "",
    comments: "",
  });
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const services = [
    { id: "genetic", name: "Генетический анализ", price: "от 900 BYN" },
    { id: "blood", name: "Анализ крови", price: "от 25 BYN" },
    { id: "bioage", name: "Био-возраст", price: "от 350 BYN" },
    { id: "dna", name: "ДНК-тест", price: "от 450 BYN" },
    { id: "nutrition", name: "Нутригенетика", price: "от 480 BYN" },
    { id: "hormones", name: "Гормональный профиль", price: "от 85 BYN" },
  ];

  const doctors = [
    { id: "ivanova", name: "Анна Иванова", specialty: "Генетик" },
    { id: "petrov", name: "Сергей Петров", specialty: "Биохимик" },
    { id: "smirnova", name: "Елена Смирнова", specialty: "Нутрициолог" },
    { id: "any", name: "Любой специалист", specialty: "" },
  ];

  const timeSlots = [
    "09:00",
    "09:30",
    "10:00",
    "10:30",
    "11:00",
    "11:30",
    "12:00",
    "14:00",
    "14:30",
    "15:00",
    "15:30",
    "16:00",
    "16:30",
    "17:00",
    "17:30",
    "18:00",
    "18:30",
    "19:00",
  ];

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);

    try {
      const appointmentData = {
        ...formData,
        date: date?.toISOString().split("T")[0],
      };

      await axios.post(`${API}/appointments`, appointmentData);
      setSubmitted(true);
      toast.success(t("appointment.success"));
    } catch (error) {
      toast.error("Ошибка при создании записи");
    } finally {
      setSubmitting(false);
    }
  };

  const canProceedToStep2 = formData.service && formData.doctor;
  const canProceedToStep3 = date && formData.time;

  if (submitted) {
    return (
      <div
        className="min-h-screen pt-20 flex items-center justify-center"
        data-testid="appointment-success"
      >
        <div className="glass-card p-12 text-center max-w-lg mx-4">
          <div className="w-20 h-20 mx-auto rounded-full bg-[#00E5A0]/10 flex items-center justify-center mb-6">
            <CheckCircle className="w-10 h-10 text-[#00E5A0]" />
          </div>
          <h2 className="text-3xl font-bold mb-4">
            {t("appointment.success")}
          </h2>
          <p className="text-[#4A5A6E] mb-6">
            Мы свяжемся с вами для подтверждения записи в ближайшее время.
          </p>
          <div className="glass-card p-4 text-left mb-6">
            <p className="text-sm text-[#4A5A6E]">
              <strong>Услуга:</strong>{" "}
              {services.find((s) => s.id === formData.service)?.name}
              <br />
              <strong>Врач:</strong>{" "}
              {doctors.find((d) => d.id === formData.doctor)?.name}
              <br />
              <strong>Дата:</strong> {date?.toLocaleDateString("ru-RU")}
              <br />
              <strong>Время:</strong> {formData.time}
            </p>
          </div>
          <button
            onClick={() => {
              setSubmitted(false);
              setStep(1);
              setFormData({
                service: "",
                doctor: "",
                time: "",
                name: "",
                phone: "",
                email: "",
                comments: "",
              });
              setDate(undefined);
            }}
            className="btn-primary"
            data-testid="new-appointment-btn"
          >
            Новая запись
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pt-20" data-testid="appointment-page">
      {/* Hero Section */}
      <section className="py-16 section-alt" data-testid="appointment-hero">
        <div className="container">
          <div className="max-w-4xl mx-auto text-center">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-6">
              Онлайн запись
            </span>
            <h1 className="text-4xl md:text-5xl font-bold mb-6">
              {t("appointment.title")}
            </h1>
            <p className="text-lg text-[#4A5A6E]">
              {t("appointment.subtitle")}
            </p>
          </div>
        </div>
      </section>

      {/* Steps Progress */}
      <section className="py-8 section-light border-b border-[#E0E7F0]">
        <div className="container">
          <div className="flex justify-center items-center gap-4">
            {[1, 2, 3].map((s) => (
              <div key={s} className="flex items-center">
                <div
                  className={`w-10 h-10 rounded-full flex items-center justify-center font-semibold transition-all duration-300 ${step >= s
                      ? "bg-[#00E5A0] text-[#0A1F44]"
                      : "bg-[#E0E7F0] text-[#94A3B8]"
                    }`}
                >
                  {s}
                </div>
                {s < 3 && (
                  <div
                    className={`w-16 md:w-24 h-1 mx-2 rounded transition-all duration-300 ${step > s ? "bg-[#00E5A0]" : "bg-[#E0E7F0]"
                      }`}
                  />
                )}
              </div>
            ))}
          </div>
          <div className="flex justify-center gap-8 md:gap-20 mt-4 text-sm">
            <span className={step >= 1 ? "text-[#00E5A0]" : "text-[#94A3B8]"}>
              Услуга
            </span>
            <span className={step >= 2 ? "text-[#00E5A0]" : "text-[#94A3B8]"}>
              Дата
            </span>
            <span className={step >= 3 ? "text-[#00E5A0]" : "text-[#94A3B8]"}>
              Данные
            </span>
          </div>
        </div>
      </section>

      {/* Form Steps */}
      <section className="py-16 section-light">
        <div className="container">
          <div className="max-w-4xl mx-auto">
            <form onSubmit={handleSubmit}>
              {/* Step 1: Service & Doctor */}
              {step === 1 && (
                <div className="space-y-8" data-testid="step-1">
                  <div className="glass-card p-8">
                    <h3 className="text-xl font-semibold mb-6">
                      {t("appointment.selectService")}
                    </h3>
                    <div className="grid md:grid-cols-2 gap-4">
                      {services.map((service) => (
                        <div
                          key={service.id}
                          onClick={() =>
                            setFormData({ ...formData, service: service.id })
                          }
                          className={`p-4 rounded-xl border-2 cursor-pointer transition-all duration-300 ${formData.service === service.id
                              ? "border-[#00E5A0] bg-[#00E5A0]/5"
                              : "border-[#E0E7F0] hover:border-[#00E5A0]/50"
                            }`}
                          data-testid={`service-option-${service.id}`}
                        >
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="font-semibold text-[#1E2A3A]">
                                {service.name}
                              </p>
                              <p className="text-sm text-[#00E5A0]">
                                {service.price}
                              </p>
                            </div>
                            {formData.service === service.id && (
                              <CheckCircle className="w-5 h-5 text-[#00E5A0]" />
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="glass-card p-8">
                    <h3 className="text-xl font-semibold mb-6">
                      {t("appointment.selectDoctor")}
                    </h3>
                    <div className="grid md:grid-cols-2 gap-4">
                      {doctors.map((doctor) => (
                        <div
                          key={doctor.id}
                          onClick={() =>
                            setFormData({ ...formData, doctor: doctor.id })
                          }
                          className={`p-4 rounded-xl border-2 cursor-pointer transition-all duration-300 ${formData.doctor === doctor.id
                              ? "border-[#00E5A0] bg-[#00E5A0]/5"
                              : "border-[#E0E7F0] hover:border-[#00E5A0]/50"
                            }`}
                          data-testid={`doctor-option-${doctor.id}`}
                        >
                          <div className="flex justify-between items-start">
                            <div className="flex items-center gap-3">
                              <div className="w-10 h-10 rounded-full bg-[#00E5A0]/10 flex items-center justify-center">
                                <User className="w-5 h-5 text-[#00E5A0]" />
                              </div>
                              <div>
                                <p className="font-semibold text-[#1E2A3A]">
                                  {doctor.name}
                                </p>
                                {doctor.specialty && (
                                  <p className="text-sm text-[#4A5A6E]">
                                    {doctor.specialty}
                                  </p>
                                )}
                              </div>
                            </div>
                            {formData.doctor === doctor.id && (
                              <CheckCircle className="w-5 h-5 text-[#00E5A0]" />
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="flex justify-end">
                    <button
                      type="button"
                      onClick={() => setStep(2)}
                      disabled={!canProceedToStep2}
                      className="btn-primary"
                      data-testid="step-1-next"
                    >
                      Далее
                    </button>
                  </div>
                </div>
              )}

              {/* Step 2: Date & Time */}
              {step === 2 && (
                <div className="space-y-8" data-testid="step-2">
                  <div className="grid md:grid-cols-2 gap-8">
                    <div className="glass-card p-8">
                      <h3 className="text-xl font-semibold mb-6 flex items-center gap-2">
                        <CalendarIcon className="w-5 h-5 text-[#00E5A0]" />
                        {t("appointment.selectDate")}
                      </h3>
                      <DayPicker
                        mode="single"
                        selected={date}
                        onSelect={setDate}
                        disabled={(date) =>
                          date < new Date() || date.getDay() === 0
                        }
                        className="rounded-md border bg-white p-3"
                        data-testid="appointment-calendar"
                      />
                    </div>

                    <div className="glass-card p-8">
                      <h3 className="text-xl font-semibold mb-6 flex items-center gap-2">
                        <Clock className="w-5 h-5 text-[#00E5A0]" />
                        {t("appointment.selectTime")}
                      </h3>
                      <div className="grid grid-cols-3 gap-3">
                        {timeSlots.map((time) => (
                          <button
                            key={time}
                            type="button"
                            onClick={() => setFormData({ ...formData, time })}
                            className={`p-3 rounded-lg text-center transition-all duration-300 ${formData.time === time
                                ? "bg-[#00E5A0] text-[#0A1F44] font-semibold"
                                : "bg-white border border-[#E0E7F0] text-[#4A5A6E] hover:border-[#00E5A0]"
                              }`}
                            data-testid={`time-slot-${time}`}
                          >
                            {time}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>

                  <div className="flex justify-between">
                    <button
                      type="button"
                      onClick={() => setStep(1)}
                      className="btn-secondary"
                      data-testid="step-2-back"
                    >
                      Назад
                    </button>
                    <button
                      type="button"
                      onClick={() => setStep(3)}
                      disabled={!canProceedToStep3}
                      className="btn-primary"
                      data-testid="step-2-next"
                    >
                      Далее
                    </button>
                  </div>
                </div>
              )}

              {/* Step 3: Contact Info */}
              {step === 3 && (
                <div className="space-y-8" data-testid="step-3">
                  <div className="glass-card p-8">
                    <h3 className="text-xl font-semibold mb-6">Ваши данные</h3>
                    <div className="space-y-6">
                      <div>
                        <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                          <User className="w-4 h-4 inline mr-2" />
                          {t("appointment.yourName")} *
                        </label>
                        <input
                          type="text"
                          value={formData.name}
                          onChange={(e) =>
                            setFormData({ ...formData, name: e.target.value })
                          }
                          className="input-field"
                          required
                          data-testid="appointment-name"
                        />
                      </div>

                      <div className="grid md:grid-cols-2 gap-6">
                        <div>
                          <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                            <Phone className="w-4 h-4 inline mr-2" />
                            {t("appointment.phone")} *
                          </label>
                          <input
                            type="tel"
                            value={formData.phone}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                phone: e.target.value,
                              })
                            }
                            className="input-field"
                            placeholder="+375 (XX) XXX-XX-XX"
                            required
                            data-testid="appointment-phone"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                            <Mail className="w-4 h-4 inline mr-2" />
                            {t("appointment.email")}
                          </label>
                          <input
                            type="email"
                            value={formData.email}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                email: e.target.value,
                              })
                            }
                            className="input-field"
                            data-testid="appointment-email"
                          />
                        </div>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                          <FileText className="w-4 h-4 inline mr-2" />
                          {t("appointment.comments")}
                        </label>
                        <textarea
                          value={formData.comments}
                          onChange={(e) =>
                            setFormData({
                              ...formData,
                              comments: e.target.value,
                            })
                          }
                          className="textarea-field"
                          rows={3}
                          data-testid="appointment-comments"
                        />
                      </div>
                    </div>
                  </div>

                  {/* Summary */}
                  <div className="glass-card p-6">
                    <h4 className="font-semibold mb-4">Итого:</h4>
                    <div className="grid md:grid-cols-4 gap-4 text-sm">
                      <div>
                        <p className="text-[#94A3B8]">Услуга</p>
                        <p className="font-medium">
                          {
                            services.find((s) => s.id === formData.service)
                              ?.name
                          }
                        </p>
                      </div>
                      <div>
                        <p className="text-[#94A3B8]">Врач</p>
                        <p className="font-medium">
                          {doctors.find((d) => d.id === formData.doctor)?.name}
                        </p>
                      </div>
                      <div>
                        <p className="text-[#94A3B8]">Дата</p>
                        <p className="font-medium">
                          {date?.toLocaleDateString("ru-RU")}
                        </p>
                      </div>
                      <div>
                        <p className="text-[#94A3B8]">Время</p>
                        <p className="font-medium">{formData.time}</p>
                      </div>
                    </div>
                  </div>

                  <div className="flex justify-between">
                    <button
                      type="button"
                      onClick={() => setStep(2)}
                      className="btn-secondary"
                      data-testid="step-3-back"
                    >
                      Назад
                    </button>
                    <button
                      type="submit"
                      disabled={submitting || !formData.name || !formData.phone}
                      className="btn-primary"
                      data-testid="appointment-submit"
                    >
                      {submitting ? "Отправка..." : t("appointment.submit")}
                    </button>
                  </div>
                </div>
              )}
            </form>
          </div>
        </div>
      </section>
    </div>
  );
};
export default AppointmentPage;
