import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Star, Quote, Send, User } from 'lucide-react';
import { toast } from 'sonner';
import axios from 'axios';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
const API = `${BACKEND_URL}/api`;

const ReviewsPage = () => {
  const { t } = useTranslation();
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    rating: 5,
    message: ''
  });
  const [submitting, setSubmitting] = useState(false);

  // Sample reviews for display
  const sampleReviews = [
    {
      id: 1,
      name: 'Анна Михайлова',
      rating: 5,
      message: 'Прекрасный центр! Сделала полный генетический анализ, результаты получила быстро. Врачи всё подробно объяснили и дали рекомендации.',
      date: '2026-02-15',
      avatar: null
    },
    {
      id: 2,
      name: 'Сергей Козлов',
      rating: 5,
      message: 'Очень доволен сервисом. Профессиональный подход, современное оборудование. Рекомендую всем, кто заботится о своём здоровье.',
      date: '2026-02-10',
      avatar: null
    },
    {
      id: 3,
      name: 'Елена Новикова',
      rating: 4,
      message: 'Отличная клиника с высоким уровнем обслуживания. Немного пришлось подождать результаты, но качество на высоте.',
      date: '2026-02-05',
      avatar: null
    },
    {
      id: 4,
      name: 'Дмитрий Волков',
      rating: 5,
      message: 'Делал ДНК-тест на родство. Всё прошло конфиденциально и профессионально. Спасибо команде Bio-Code!',
      date: '2026-02-28',
      avatar: null
    },
    {
      id: 5,
      name: 'Ольга Соколова',
      rating: 5,
      message: 'Нутригенетический анализ помог мне наконец разобраться с питанием. Теперь знаю, что именно мне подходит. Очень благодарна!',
      date: '2026-01-20',
      avatar: null
    },
  ];

  useEffect(() => {
    fetchReviews();
  }, []);

  const fetchReviews = async () => {
    try {
      const response = await axios.get(`${API}/reviews`);
      setReviews([...sampleReviews, ...response.data]);
    } catch (error) {
      setReviews(sampleReviews);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);

    try {
      const response = await axios.post(`${API}/reviews`, formData);
      setReviews([response.data, ...reviews]);
      setFormData({ name: '', email: '', rating: 5, message: '' });
      toast.success('Спасибо за ваш отзыв!');
    } catch (error) {
      toast.error('Ошибка при отправке отзыва');
    } finally {
      setSubmitting(false);
    }
  };

  const renderStars = (rating, interactive = false, onRate = null) => {
    return (
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <button
            key={star}
            type={interactive ? 'button' : undefined}
            onClick={interactive ? () => onRate(star) : undefined}
            className={`${interactive ? 'cursor-pointer' : 'cursor-default'}`}
            disabled={!interactive}
          >
            <Star
              className={`w-5 h-5 ${
                star <= rating ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300'
              } ${interactive ? 'hover:text-yellow-400 transition-colors duration-200' : ''}`}
            />
          </button>
        ))}
      </div>
    );
  };

  const averageRating = reviews.length > 0
    ? (reviews.reduce((sum, r) => sum + r.rating, 0) / reviews.length).toFixed(1)
    : '5.0';

  return (
    <div className="min-h-screen pt-20" data-testid="reviews-page">
      {/* Hero Section */}
      <section className="py-20 section-alt" data-testid="reviews-hero">
        <div className="container">
          <div className="max-w-4xl mx-auto text-center">
            <span className="inline-block px-4 py-2 rounded-full bg-[#00E5A0]/10 text-[#00E5A0] text-sm font-semibold mb-6">
              Отзывы
            </span>
            <h1 className="text-4xl md:text-6xl font-bold mb-6">{t('reviews.title')}</h1>
            <p className="text-lg text-[#4A5A6E] leading-relaxed mb-8">
              {t('reviews.subtitle')}
            </p>
            
            {/* Rating Summary */}
            <div className="glass-card inline-flex items-center gap-4 px-8 py-4">
              <div className="text-center">
                <p className="text-4xl font-bold text-[#1E2A3A]">{averageRating}</p>
                <div className="flex justify-center mt-1">
                  {renderStars(Math.round(parseFloat(averageRating)))}
                </div>
              </div>
              <div className="h-12 w-px bg-[#E0E7F0]"></div>
              <div className="text-left">
                <p className="text-2xl font-bold text-[#1E2A3A]">{reviews.length}</p>
                <p className="text-sm text-[#4A5A6E]">отзывов</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Add Review Form */}
      <section className="py-16 section-light" data-testid="add-review-section">
        <div className="container">
          <div className="max-w-2xl mx-auto">
            <div className="glass-card p-8">
              <h2 className="text-2xl font-bold mb-6 text-center">{t('reviews.addReview')}</h2>
              
              <form onSubmit={handleSubmit} className="space-y-6">
                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                      {t('reviews.name')}
                    </label>
                    <input
                      type="text"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      className="input-field"
                      required
                      data-testid="review-name-input"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                      {t('reviews.email')}
                    </label>
                    <input
                      type="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      className="input-field"
                      required
                      data-testid="review-email-input"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                    {t('reviews.rating')}
                  </label>
                  <div data-testid="review-rating">
                    {renderStars(formData.rating, true, (rating) => setFormData({ ...formData, rating }))}
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#1E2A3A] mb-2">
                    {t('reviews.message')}
                  </label>
                  <textarea
                    value={formData.message}
                    onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                    className="textarea-field"
                    rows={4}
                    required
                    data-testid="review-message-input"
                  />
                </div>

                <button
                  type="submit"
                  disabled={submitting}
                  className="btn-primary w-full flex items-center justify-center gap-2"
                  data-testid="review-submit-btn"
                >
                  {submitting ? 'Отправка...' : t('reviews.submit')}
                  <Send className="w-5 h-5" />
                </button>
              </form>
            </div>
          </div>
        </div>
      </section>

      {/* Reviews List */}
      <section className="py-16 section-alt" data-testid="reviews-list-section">
        <div className="container">
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {reviews.map((review, index) => (
              <div
                key={review.id || index}
                className="glass-card p-6 service-card"
                data-testid={`review-card-${index}`}
              >
                <Quote className="w-8 h-8 text-[#00E5A0]/30 mb-4" />
                
                <p className="text-[#4A5A6E] mb-6 leading-relaxed">
                  "{review.message}"
                </p>

                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-[#00E5A0]/10 flex items-center justify-center">
                      <User className="w-5 h-5 text-[#00E5A0]" />
                    </div>
                    <div>
                      <p className="font-semibold text-[#1E2A3A]">{review.name}</p>
                      <p className="text-xs text-[#94A3B8]">
                        {new Date(review.date).toLocaleDateString('ru-RU')}
                      </p>
                    </div>
                  </div>
                  {renderStars(review.rating)}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
};
export default ReviewsPage;